mapper.select:
select A.* from ( select @ROWNUM := @ROWNUM + 1 as ROWNUM, TB.* from ( select notice_seq_no as noticeSeqNo , notice_title as noticeTitle , notice_content as noticeContent , notice_writer as noticeWriter , notice_writer_name as noticeWriterName , notice_hit_cnt as noticeHitCnt , notice_del_yn as noticeDelYn , notice_date as noticeDate , notice_up_date as noticeUpdate , notice_up_user as noticeUpUser from tb_notice where notice_del_yn = 'N'
and notice_title like CONCAT('%', #{searchWord}, '%')
and notice_content like CONCAT('%', #{searchWord}, '%')
and (notice_title like CONCAT('%', #{searchWord}, '%') OR notice_content like CONCAT('%', #{searchWord}, '%'))
and notice_writer_name = #{searchWord}
order by notice_seq_no DESC ) TB, ( select @ROWNUM := 0 ) R ) A where A.ROWNUM between #{startRow} and #{endRow}

mapper.update:
update tb_notice set 
	notice_hit_cnt = notice_hit_cnt + 1
where notice_seq_no = #{noticeSeqNo}

mapper.insert:

	select
		case count(*) when 0 then 1 else max(notice_seq_no) + 1 end as noticeSeqNo
	from tb_notice				

insert into tb_notice (
	  notice_seq_no
	, notice_title
	, notice_content
	, notice_writer
	, notice_writer_name
	, notice_hit_cnt
	, notice_del_yn
	, notice_date
	, notice_up_date
	, notice_up_user	
) values (
	#{noticeSeqNo}
	, #{noticeTitle}
	, #{noticeContent}
	, #{noticeWriter}
	, #{noticeWriterName}
	, 0
	, COALESCE(#{noticeDelYn}, 'N')
	, now()
	, now()
	, #{noticeWriter}
)

mapper.update:
update tb_notice set 
		notice_title 			= #{noticeTitle}
	, 	notice_content 		= #{noticeContent}
	,	notice_up_date		= now()
	,	notice_up_user		= #{noticeUpUser}
where 
	notice_seq_no = #{noticeSeqNo}


update tb_notice set
		notice_del_yn 	= 'Y'
	, 	notice_up_date 	= now()
	, 	notice_up_user	= #{noticeUpUser}
where
	notice_seq_no = #{noticeSeqNo}
